import{_ as t,o as i,c as s,a3 as a}from"./chunks/framework.16qmHapV.js";const k=JSON.parse('{"title":"Server integration","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"guide/server.md","filePath":"guide/server.md"}'),n={name:"guide/server.md"};function r(o,e,h,l,p,d){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="server-integration" tabindex="-1">Server integration <a class="header-anchor" href="#server-integration" aria-label="Permalink to &quot;Server integration&quot;">​</a></h1><p>A PAI server implements the content operations described in <a href="/pai-website/spec/service.html">SERVICE.md</a>. A service provider can integrate these operations into an existing platform. Its account system issues publisher credentials, its storage retains documents and versions, and its product supplies any online editing interface.</p><p>The reference server demonstrates the wire behavior using a local credential file and filesystem snapshots. It listens on loopback. The instructions below operate from the PAI project directory after <a href="/pai-website/guide/installation.html">installation</a>.</p><h2 id="run-the-reference-server" tabindex="-1">Run the reference server <a class="header-anchor" href="#run-the-reference-server" aria-label="Permalink to &quot;Run the reference server&quot;">​</a></h2><p>Create a private local credential file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-type=module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NODE&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import { randomBytes } from &#39;node:crypto&#39;;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import { writeFileSync } from &#39;node:fs&#39;;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const entries = [{ publisherId: &#39;demo:alice&#39;, token: randomBytes(32).toString(&#39;hex&#39;) }];</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">writeFileSync(&#39;.local/publishers.json&#39;, JSON.stringify(entries), { flag: &#39;wx&#39;, mode: 0o600 });</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">console.log(&#39;Created .local/publishers.json&#39;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NODE</span></span></code></pre></div><p>The command fails if that file already exists, preserving its credentials. The file contains an array of <code>{publisherId, token}</code> entries; add another entry to give a second publisher an independent credential. Both publisher IDs and tokens must be unique in the reference configuration.</p><p>Start a service on port 4747:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAI_PUBLISHERS_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.local/publishers.json&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/provider.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4747</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .pai-data/content</span></span></code></pre></div><p>The startup line contains the actual service URL. Passing port <code>0</code> selects an available local port. The final argument is the snapshot directory. Reuse that directory to retain documents and historical versions after a restart. Stop the server with Ctrl+C.</p><p>In another terminal in the same directory, set the client credential without printing it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PAI_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;JSON.parse(require(&#39;node:fs&#39;).readFileSync(&#39;.local/publishers.json&#39;,&#39;utf8&#39;))[0].token&quot;)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4747</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/dist/event.pai</span></span></code></pre></div><p>The configured publisher is returned in the publication response. Public GET requests need no credential. <code>PAI_OWNER_ID</code> and <code>PAI_OWNER_TOKEN</code> remain available for the single-publisher local trial; a client normally uses <code>PAI_TOKEN</code>.</p><h2 id="implement-the-content-profile" tabindex="-1">Implement the content profile <a class="header-anchor" href="#implement-the-content-profile" aria-label="Permalink to &quot;Implement the content profile&quot;">​</a></h2><p>Start with the <a href="/pai-website/spec/schemas/service.schema.json">discovery schema</a> and <a href="/pai-website/spec/fixtures/">fixed exchanges</a>. The following table maps protocol behavior to platform integration work.</p><table tabindex="0"><thead><tr><th>Area</th><th>Implementation work</th></tr></thead><tbody><tr><td>Discovery</td><td>Serve <code>/.well-known/pai.json</code>; declare the supported protocol, capabilities, formats, authentication, and operation URLs</td></tr><tr><td>Authentication</td><td>Resolve the write credential to a publisher; check the selected resource&#39;s ownership for PUT</td></tr><tr><td>File ingestion</td><td>Parse ZIP or HTML data without executing uploaded code; validate the content model and image references</td></tr><tr><td>Identity and versions</td><td>Maintain a resource for each publisher/document pair; retain immutable snapshots and the latest-version pointer</td></tr><tr><td>Retries</td><td>Compare document revision and canonical content; return the stored snapshot for an equivalent retry</td></tr><tr><td>Representations</td><td>Supply versioned structured content, the original file, and a reading page</td></tr><tr><td>Sources</td><td>Keep block source links bound to their publication version and original images</td></tr><tr><td>Errors</td><td>Return the specified HTTP status and machine-readable <code>error</code> code</td></tr></tbody></table><p>The common content model is the interoperability boundary. A server can store its data in a database and images in object storage. The reference server&#39;s directory layout is an implementation detail.</p><p>The reference file loader returns validated image data as <code>Uint8Array</code>. Keep those bytes binary when storing or processing resources. <code>writePaiFile()</code> writes ZIP resources directly and encodes them for standalone HTML. Use <code>toJSONDocument()</code> for complete Base64 document serialization; ordinary structured-content responses contain image metadata only. This API change leaves the protocol and file schemas unchanged. <a href="/pai-website/guide/file-tools.html#content-representation">File API details</a> describe the conversion helpers.</p><p>Publication preserves the first file stored for a snapshot. A cross-container retry returns that same snapshot and original file. Use <code>downloadFormat</code> and <code>downloadMediaType</code> to describe its actual form. The reading page can use the server&#39;s own renderer and editor. The reference implementation generates it from validated data using the bundled editor, without executing uploaded HTML programs.</p><p>Apply the <a href="/pai-website/spec/hash.html">content hash rules</a> when comparing versions. Image bytes participate in content identity; ZIP compression bytes and the HTML editor program do not. Preserve the historical hash algorithm marker when returning an older snapshot.</p><p>Use <code>contentFingerprint()</code> for the current algorithm. The reference implementation converts binary documents with <code>toJSONDocument()</code> before checking the historical <code>pai-json-sha256-v0.6</code> algorithm, which includes Base64 data. Direct JSON serialization of a typed array would change that historical representation.</p><p>For network deployment, serve the origin over HTTPS and connect authentication to the platform&#39;s credential lifecycle. The reference process binds to <code>127.0.0.1</code>; a deployment can place it behind a same-origin reverse proxy. The current client expects <code>/.well-known/pai.json</code> at the origin root and follows same-origin operation links.</p><p>The reference implementation limits an upload, ZIP-expanded data, and generated reading HTML to 64 MiB each. Its file tools also limit ZIP entries and JSON depth. These are implementation limits, not a protocol-wide storage quota. A deployment should document its own limits and return the specified error when it rejects a file.</p><h2 id="check-an-implementation" tabindex="-1">Check an implementation <a class="header-anchor" href="#check-an-implementation" aria-label="Permalink to &quot;Check an implementation&quot;">​</a></h2><p>Run the checker against an HTTPS origin or a loopback HTTP origin:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/check-service.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4747</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/check-service.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4747</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --resource</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4747/resources/RESOURCE_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read-report.json</span></span></code></pre></div><p>Replace <code>RESOURCE_ID</code> with a returned resource ID. Default checks perform public reads, select the requested resource or the first catalogue item, and inspect discovery, declared links, resource/version metadata, structured content, the downloaded file, content hashes, assets, source-link origins, and availability of the reading representation. An empty catalogue is reported as skipped content checks. Browser verification checks whether a source link reaches the intended block and whether the document renders correctly.</p><p>Exercise writes on a test deployment:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/check-service.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4747</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --write</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write-report.json</span></span></code></pre></div><p><code>--write</code> requires <code>PAI_TOKEN</code>. It publishes a uniquely identified synthetic document, retries with the other container when supported, and tests updates and historical reads when advertised. Test resources remain in the service; the current draft has no deletion endpoint. Use a dedicated test publisher or test service for repeated runs.</p><p>The report is JSON on standard output. <code>--output</code> writes the same report to a new file and rejects an existing path. Exit status is <code>0</code> when the performed checks pass, <code>1</code> when a check fails, and <code>2</code> for invalid command usage. Reports list skipped operations when the corresponding capability or material is unavailable.</p><p>The checker follows declared links, refuses redirects and cross-origin links, and sends the token only with explicit write operations. The report identifies the content profile operations performed. Check rendering and editor interactions in the application that consumes the service.</p><h2 id="keep-the-implementation-aligned" tabindex="-1">Keep the implementation aligned <a class="header-anchor" href="#keep-the-implementation-aligned" aria-label="Permalink to &quot;Keep the implementation aligned&quot;">​</a></h2><p>Run the fixed specification tests and the service tests after changing ingestion, authorization, revision handling, or response generation:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:spec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Record the protocol version, supported content/container versions, and deployment limits with each release. Changes to platform accounts, storage, or editor internals can stay within the same protocol version when the externally observable requirements continue to hold.</p>`,36)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
